import type { JSX } from 'react';
import { useSettings, ChordPosition } from 'hooks';
import { Diagram } from 'components/fretboard';
import React from 'react';
import { useGuitarChord } from '../hooks';
import { DotText, FretNumberPosition } from 'components/fretboard/options';

export const ChordContent = (): JSX.Element => {
  const { chord, printRef, printStyle } = useGuitarChord();
  const { orientation } = useSettings();

  return (
    <div className="flex flex-col items-center" id="chord-content" ref={printRef}>
      <style type="text/css" media="print">
        {printStyle(orientation)}
      </style>
      {chord && (
        <div className="flex flex-row items-center">
          <p className="text-3xl pt-2">{`${chord.key} ${chord.suffix}`}</p>
        </div>
      )}
      <div className="flex flex-row items-center">
        {chord &&
          chord.positions &&
          chord.positions.map((position, chordPosition) => (
            <ChordDiagram
              key={`chord-${chordPosition}`}
              chord={position}
              chordPosition={chordPosition}
              diagramCount={chord?.positions?.length}
            />
          ))}
      </div>
    </div>
  );
};

type ChordDiagramProps = {
  chord?: ChordPosition;
  chordPosition?: number;
  diagramCount?: number;
};

const ChordDiagram = ({ chord, chordPosition, diagramCount }: ChordDiagramProps): JSX.Element => {
  return (
    <Diagram
      key={`chord-diagram.${chordPosition || 0}`}
      className=""
      diagramCount={diagramCount}
      text={DotText.NOTE}
      chord={chord}
      fretNumbersPosition={FretNumberPosition.LEFT}
    />
  );
};
